    input [3:0] I,
    input clk,
    output reg [1:0] Y
);

reg [1:0] stage1_out;
reg [1:0] stage2_out;

always @ (posedge clk) begin
    stage1_out <= {I[1], I[0]};
    stage2_out <= {I[3], I[2]};
