	input [7:0] x,
	input [7:0] y,
	output out
);

wire [9:0] and_outputs;
wire [4:0] or_outputs;

genvar i;

generate
	// Create 8 AND gates
	for(i = 0; i < 8; i = i + 1)
	begin: and_1st_row
		assign and_outputs[i] = x[i] & y[i];
